      position: absolute; top: 16px; left: 50%; transform: translateX(-50%);
      z-index: 20; display: none; max-width: 80%;
      font-family: system-ui, sans-serif; color: #ffd7d7;
      background: rgba(120, 20, 20, 0.9); border-radius: 8px; padding: 10px 14px;
      font-size: 0.85rem;
    }
  </style>
</head>
