  <div id="loading">
    <div>Loading Manhattan 3D Map…</div>
    <div class="phase" id="phase">Initializing…</div>
  </div>

  <div id="error"></div>

  <div id="stats" class="panel">
    <h3>Subway Accessibility</h3>
